def finding(row):
    fid,name,desc,kind,refs,vkind,required=row
    return {"id":fid,"name":name,"description":desc,"source_refs":refs,"questions":[
        {"id":fid+"-q01","text":f"What exact identities, roles, classes, values, links and unknowns define {name.lower()} for this case?","kind":kind,"answer_data":["identities and roles","class and profile","values and links","unknowns"]},
        {"id":fid+"-q02","text":f"Which forum authority, procedural rule, filing, evidence, order and event or knowledge time supports {name.lower()}?","kind":"evidence","answer_data":["forum and authority","rule","record or evidence","order","times"]},
        {"id":fid+"-q03","text":f"How may {name.lower()} be validated, contested, corrected, superseded, retained or disclosed without adjudicating the dispute or erasing history?","kind":"validation","answer_data":["validation","contest route","non-adjudication","successor","retention and access"]}],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured forum-qualified case data for "+name.lower()+".","value_kind":vkind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing case record for "+name.lower()+" with rule, event and knowledge time, provenance and access marking.","media_or_form":["logical court or arbitration case record","authoritative docket or procedural evidence reference"],"serial":True,"identity_strategy":"Case identifier plus "+fid+" assertion or event identifier; party, title, forum, date and hash never identify the case alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    return {"bundles":[{"id":bid,"name":name,"description":desc,"rationale":why,"source_refs":refs,"layers":[{"id":lid,"name":lname,"description":ldesc,"source_refs":lrefs,"findings":[finding(x) for x in findings]} for lid,lname,ldesc,lrefs,findings in layers]} for bid,name,desc,why,refs,layers in BUNDLES]}

